def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict[chain[0]].append(chain[-1])

    visited = set()
    path = []

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        path.append(node)
        for neighbor in chain_dict.get(node, []):
            dfs(neighbor)
        path.pop()

    dfs(chain[0])

    return ','.join(path)
